class Solution {
    public String largestTimeFromDigits(int[] arr) {
        int maxTime = -1;
        String res = "";
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (j == i) continue;
                for (int k = 0; k < 4; k++) {
                    if (k == i || k == j) continue;
                    int l = 6 - i - j - k;
                    int h = arr[i] * 10 + arr[j];
                    int m = arr[k] * 10 + arr[l];
                    if (h < 24 && m < 60) {
                        int total = h * 60 + m;
                        if (total > maxTime) {
                            maxTime = total;
                            res = "" + arr[i] + arr[j] + ":" + arr[k] + arr[l];
                        }
                    }
                }
            }
        }
        return res;
    }
}

