    for (let i = 0; i < 4; i++) {
        for (let j = 0; j < 4; j++) {
            if (j === i) continue;
            for (let k = 0; k < 4; k++) {
                if (k === i || k === j) continue;
                const l = 6 - i - j - k;
                const h = arr[i] * 10 + arr[j];
                const m = arr[k] * 10 + arr[l];
                if (h < 24 && m < 60) {
